<?php $pageTitle='Laporan Penjualan';require __DIR__.'/../partials/header.php';require __DIR__.'/../partials/sidebar.php';?><main class="main"><div class="container-fluid"><?php require __DIR__.'/../partials/navbar.php';?><div class="report-head"><div><div class="eyebrow">LAPORAN TOKO</div><h2 class="mb-1">Laporan <?=date('F Y',strtotime($start))?></h2><p class="text-muted">Penjualan, produk terjual, dan posisi stok berdasarkan periode.</p></div><button class="btn btn-primary" onclick="window.print()"><i class="bi bi-printer"></i> Cetak / Simpan PDF</button></div><div class="card-shell mb-4"><form class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">Bulan</label><select class="form-select" name="month"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$m===$month?'selected':''?>><?=date('F',mktime(0,0,0,$m,1))?></option><?php endfor;?></select></div><div class="col-md-3"><label class="form-label">Tahun</label><select class="form-select" name="year"><?php for($y=date('Y')-2;$y<=date('Y')+1;$y++):?><option <?=$y===$year?'selected':''?>><?=$y?></option><?php endfor;?></select></div><div class="col-md-3"><button class="btn btn-outline-secondary w-100"><i class="bi bi-filter"></i> Terapkan filter</button></div></form></div><div class="row g-4 mb-4"><?php foreach([['Total transaksi',$summary['transaksi'],'bi-receipt'],['Pendapatan',rupiah($summary['pendapatan']),'bi-wallet2'],['Produk terjual',number_format($summary['produk_terjual']),'bi-box-seam'],['Rata-rata transaksi',rupiah($summary['rata_rata']),'bi-graph-up-arrow']] as $stat):?><div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-icon"><i class="bi <?=$stat[2]?>"></i></div><div class="text-muted small"><?=$stat[0]?></div><div class="stat-number"><?=$stat[1]?></div></div></div><?php endforeach;?></div><div class="row g-4 mb-4"><?php foreach([['Stok tersedia',number_format($stock['unit']).' unit',$stock['jenis'].' jenis produk','bi-boxes'],['Nilai stok',rupiah($stock['nilai']),'Harga jual × stok saat ini','bi-cash-stack'],['Stok menipis',count($lowStock).' produk','Batas peringatan: ≤ 5 unit','bi-exclamation-triangle']] as $stat):?><div class="col-sm-6 col-xl-4"><div class="stat-card"><div class="stat-icon"><i class="bi <?=$stat[3]?>"></i></div><div class="text-muted small"><?=$stat[0]?></div><div class="stat-number"><?=$stat[1]?></div><div class="text-muted small"><?=$stat[2]?></div></div></div><?php endforeach;?></div><div class="row g-4 mb-4"><div class="col-lg-5"><div class="card-shell"><div class="section-title">Stok menipis</div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Produk</th><th class="text-end">Stok</th><th class="text-end">Nilai</th></tr></thead><tbody><?php if(!$lowStock):?><tr><td colspan="3" class="text-center text-muted py-4">Semua stok masih aman.</td></tr><?php endif;?><?php foreach($lowStock as $p):?><tr><td><?=e($p['nama'])?></td><td class="text-end"><span class="badge text-bg-warning"><?=number_format($p['stok'])?></span></td><td class="text-end"><?=rupiah($p['stok']*$p['harga'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-7"><div class="card-shell"><div class="section-title">Penjualan berdasarkan metode pembayaran</div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Metode</th><th class="text-end">Transaksi</th><th class="text-end">Total</th></tr></thead><tbody><?php if(!$payments):?><tr><td colspan="3" class="text-center text-muted py-4">Belum ada pembayaran.</td></tr><?php endif;?><?php foreach($payments as $p):?><tr><td><span class="badge text-bg-light"><?=strtoupper(e($p['payment_method']))?></span></td><td class="text-end"><?=number_format($p['transaksi'])?></td><td class="text-end fw-semibold"><?=rupiah($p['total'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><div class="row g-4"><div class="col-xl-8"><div class="card-shell"><div class="section-title">Rincian transaksi</div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>No</th><th>Waktu</th><th>Kasir</th><th>Member</th><th>Metode</th><th class="text-end">Total</th></tr></thead><tbody><?php if(!$transactions):?><tr><td colspan="6" class="text-center text-muted py-5">Belum ada transaksi pada periode ini.</td></tr><?php endif;?><?php foreach($transactions as $r):?><tr><td>#<?=$r['id']?></td><td><?=date('d/m/Y H:i',strtotime($r['tanggal']))?></td><td><?=e($r['kasir'])?></td><td><?=e($r['pelanggan'])?></td><td><span class="badge text-bg-light"><?=strtoupper(e($r['payment_method']))?></span></td><td class="text-end fw-semibold"><?=rupiah($r['total'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-xl-4"><div class="card-shell mb-4"><div class="section-title">Top 5 produk terlaris</div><?php if(!$topProducts):?><p class="text-muted">Belum ada data produk terjual.</p><?php endif;?><?php foreach($topProducts as $i=>$p):?><div class="top-product"><span class="rank"><?=($i+1)?></span><div><strong><?=e($p['nama'])?></strong><small><?=number_format($p['jumlah'])?> item · <?=rupiah($p['pendapatan'])?></small></div></div><?php endforeach;?></div><div class="card-shell"><div class="section-title">Penjualan per kategori</div><?php if(!$categories):?><p class="text-muted">Belum ada data kategori.</p><?php endif;?><?php foreach($categories as $p):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e($p['kategori']??'Tanpa kategori')?><small class="d-block text-muted"><?=number_format($p['jumlah'])?> item</small></span><strong><?=rupiah($p['total'])?></strong></div><?php endforeach;?></div></div></div></div></div><?php require __DIR__.'/../partials/footer.php';?>
<script>document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('.report-head button');if(b)b.onclick=()=>window.open('?page=laporan/print&month=<?=$month?>&year=<?=$year?>','_blank')})</script>
